import random
import time
from functools import wraps


def retry(max_attempts=5, base_delay=0.5, max_delay=30.0, factor=2.0,
          jitter=True, exceptions=(Exception,)):
    """Retry the decorated callable with exponential backoff.

    Sleeps base_delay * factor**attempt between tries, capped at max_delay.
    With jitter, the sleep is drawn uniformly from [0, delay]. The last
    exception is re-raised once max_attempts is exhausted.
    """
    if max_attempts < 1:
        raise ValueError("max_attempts must be >= 1")

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(max_attempts):
                try:
                    return func(*args, **kwargs)
                except exceptions:
                    if attempt == max_attempts - 1:
                        raise
                    delay = min(base_delay * factor ** attempt, max_delay)
                    if jitter:
                        delay = random.uniform(0, delay)
                    time.sleep(delay)
        return wrapper
    return decorator
